<?php require 'config/database.php';require 'config/app.php';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){check_token();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=preg_replace('/\D/','',$_POST['phone']??'');$pw=$_POST['password']??'';if(mb_strlen($name)<2)$errors[]='Enter your name.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email.';if(strlen($phone)<10||strlen($phone)>13)$errors[]='Enter a valid mobile number.';if(strlen($pw)<8)$errors[]='Password must be at least 8 characters.';if(!$errors){try{$s=$pdo->prepare("INSERT INTO players(full_name,email,phone,password_hash) VALUES(?,?,?,?)");$s->execute([$name,$email,$phone,password_hash($pw,PASSWORD_DEFAULT)]);$_SESSION['player_id']=(int)$pdo->lastInsertId();$_SESSION['player_name']=$name;flash('success','Account created. Welcome to the Arena.');go('dashboard.php');}catch(PDOException $e){$errors[]='That email may already be registered.';}}}$pageTitle='Join the Arena';require 'includes/header.php';?>
<div class="auth"><div class="auth-promo"><div class="eyebrow">YOUR JOURNEY STARTS HERE</div><h1>JOIN THE<br><span>ARENA.</span></h1><p>Create your player account, build your squad, and keep every entry in one place.</p><p>✦ One dashboard for every entry<br>✦ Track payment and registration status<br>✦ Follow results and leaderboard movement</p><div class="watermark">BA<span>•</span></div></div><div class="auth-form"><div class="eyebrow">PLAYER ACCOUNT / 01</div><h2>Create account</h2><p class="muted">Already registered? <a href="login.php">Log in</a>.</p><?php foreach($errors as $er):?><div class="alert alert-danger"><?=e($er)?></div><?php endforeach;?><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(token())?>"><label>Full name<input name="name" required maxlength="100" value="<?=e($_POST['name']??'')?>"></label><label>Email address<input type="email" name="email" required value="<?=e($_POST['email']??'')?>"></label><label>Mobile number<input name="phone" required inputmode="tel" value="<?=e($_POST['phone']??'')?>"></label><label>Password<input type="password" name="password" required minlength="8"></label><button class="btn btn-hot btn-lg w-100">Create account ↗</button></form></div></div><?php require 'includes/footer.php';?>
